from __future__ import annotations

from typing import Any

from pipeline.tests.test_review_2026_11_03 import same

SHOW = """def show(f):
    try:
        print(repr(f()))
    except Exception as e:
        print(type(e).__name__, e)
"""

LOGGED = """class L:
    log = []
    def __init__(self, v):
        self.v = v
    def __lt__(self, other):
        L.log.append((self.v, other.v))
        return self.v < other.v
def digest(values, **kw):
    L.log = []
    out = sorted([L(v) for v in values], **kw)
    total = 0
    for x, y in L.log:
        total = (total * 31 + x * 3 + y) % 1000000007
    print(len(values), len(L.log), total, [o.v for o in out[:3]], [o.v for o in out[-3:]])
def lcg(n, seed, mod):
    out = []
    x = seed
    for _ in range(n):
        x = (x * 1103515245 + 12345) % 2147483648
        out.append(x % mod)
    return out
"""

